import React from 'react';

function MenuWorkspace({ title, description, icon, workspaceLabel, testId }) {
  return (
    <div className="section-page" data-testid={testId}>
      <p className="eyebrow">WORKSPACE</p>
      <h1>{title}</h1>
      <p className="dashboard-subtitle">{description}</p>
      <section className="section-empty" aria-label={`${title} workspace`}>
        <span className="section-empty-mark"><i className={`mdi ${icon}`} aria-hidden="true" /></span>
        <h2>{workspaceLabel}</h2>
        <p>This dedicated page is ready for its menu-specific content.</p>
      </section>
    </div>
  );
}

export function ShopPage() {
  return (
    <div className="section-page shop-page" data-testid="shop-page">
      <h1>Shop</h1>
      <p className="dashboard-subtitle">Manage your shop details.</p>
      <section className="shop-form-card" aria-label="Shop details">
        <form className="shop-form">
          <div className="shop-form-field">
            <label htmlFor="shop-name">Shop Name <span aria-hidden="true">*</span></label>
            <input id="shop-name" name="shopName" type="text" placeholder="Shop Name" />
          </div>
          <div className="shop-form-field">
            <label htmlFor="shop-address">Shop Address</label>
            <textarea id="shop-address" name="shopAddress" rows="4" />
          </div>
          <div className="shop-form-field">
            <label htmlFor="shop-contact-person">Shop Contact Person</label>
            <input id="shop-contact-person" name="contactPerson" type="text" placeholder="Shop Contact Person" />
          </div>
          <div className="shop-form-field">
            <label htmlFor="shop-contact-number">Contact Number</label>
            <input id="shop-contact-number" name="contactNumber" type="tel" placeholder="Contact Number" />
          </div>
          <div className="shop-form-actions">
            <button className="shop-save-button" type="button">Update</button>
            <button className="shop-cancel-button" type="button">Cancel</button>
          </div>
        </form>
      </section>
    </div>
  );
}

export function PartyPage() {
  return (
    <MenuWorkspace
      title="Party"
      description="Party workspace"
      icon="mdi-account-group-outline"
      workspaceLabel="Party"
      testId="party-page"
    />
  );
}

export function UserPage() {
  return (
    <MenuWorkspace
      title="User"
      description="User workspace"
      icon="mdi-account-outline"
      workspaceLabel="User"
      testId="user-page"
    />
  );
}

export function GenericMenuPage({ title }) {
  return (
    <MenuWorkspace
      title={title}
      description={`${title} workspace`}
      icon="mdi-view-grid-outline"
      workspaceLabel={title}
      testId="menu-page"
    />
  );
}
